@Test
public void testDeprecated() throws ParseException {
    final Set<Option> handler = new HashSet<>();
    parser = DefaultParser.builder().setDeprecatedHandler(handler::add).build();
    final Option opt1 = Option.builder().option("d1").deprecated().build();
    // @formatter:off
    final Option opt2 = Option.builder().option("d2").deprecated(DeprecatedAttributes.builder()
            .setForRemoval(true)
            .setSince("1.0")
            .setDescription("Do this instead.").get()).build();
    // @formatter:on
    final Option opt3 = Option.builder().option("a").build();
    // @formatter:off
    final CommandLine cl = parser.parse(new Options()
            .addOption(opt1)
            .addOption(opt2)
            .addOption(opt3),
            new String[] {"-d1", "-d2", "-a"});
    // @formatter:on
    // Trigger handler:
    assertTrue(cl.hasOption(opt1.getOpt()));
    assertTrue(cl.hasOption(opt2.getOpt()));
    assertTrue(cl.hasOption(opt3.getOpt()));
    // Assert handler was triggered
    assertTrue(handler.contains(opt1));
    assertTrue(handler.contains(opt2));
    assertFalse(handler.contains(opt3));
}

proposals.refactored:
private static final String[] ARGS = {"-d1", "-d2", "-a"};

/**
 * Parses the given arguments using a {@link DefaultParser} configured with a deprecated‑option
 * handler that adds the encountered {@link Option}s to the supplied {@code handler} set.
 *
 * @param handler the set that will receive deprecated options
 * @return the {@link CommandLine} produced by the parser
 */
private CommandLine parseWithDeprecatedHandler(final Set<Option> handler) {
    parser = DefaultParser.builder()
            .setDeprecatedHandler(handler::add)
            .build();

    final Option opt1 = Option.builder()
            .option("d1")
            .deprecated()
            .build();

    final Option opt2 = Option.builder()
            .option("d2")
            .deprecated(DeprecatedAttributes.builder()
                    .setForRemoval(true)
                    .setSince("1.0")
                    .setDescription("Do this instead.")
                    .get())
            .build();

    final Option opt3 = Option.builder()
            .option("a")
            .build();

    final Options options = new Options()
            .addOption(opt1)
            .addOption(opt2)
            .addOption(opt3);

    return assertDoesNotThrow(() -> parser.parse(options, ARGS),
            "Parsing should not throw a ParseException");
}

@Test
void testDeprecated_parsingOptions() {
    final Set<Option> handler = new HashSet<>();
    final CommandLine cl = parseWithDeprecatedHandler(handler);

    assertAll("Parsed options should be present",
            () -> assertTrue(cl.hasOption("d1"),
                    "Option 'd1' (deprecated) must be reported as present"),
            () -> assertTrue(cl.hasOption("d2"),
                    "Option 'd2' (deprecated with attributes) must be reported as present"),
            () -> assertTrue(cl.hasOption("a"),
                    "Option 'a' (non‑deprecated) must be reported as present")
    );
}

@Test
void testDeprecated_handlerInvocation() {
    final Set<Option> handler = new HashSet<>();
    parseWithDeprecatedHandler(handler); // parsing triggers the handler

    assertAll("Deprecated‑option handler should be invoked correctly",
            () -> assertTrue(handler.stream().anyMatch(o -> "d1".equals(o.getOpt())),
                    "Handler must contain option 'd1'"),
            () -> assertTrue(handler.stream().anyMatch(o -> "d2".equals(o.getOpt())),
                    "Handler must contain option 'd2'"),
            () -> assertFalse(handler.stream().anyMatch(o -> "a".equals(o.getOpt())),
                    "Handler must not contain non‑deprecated option 'a'")
    );
}

