/**
 * Helper container for the values produced by the concurrency test setup.
 */
private static final class ConcurrencyTestResult {
    final TypeAdapter<?> mainAdapter;
    final TypeAdapter<?> threadAdapter;
    final int adapterInstancesCreated;

    ConcurrencyTestResult(TypeAdapter<?> mainAdapter,
                          TypeAdapter<?> threadAdapter,
                          int adapterInstancesCreated) {
        this.mainAdapter = mainAdapter;
        this.threadAdapter = threadAdapter;
        this.adapterInstancesCreated = adapterInstancesCreated;
    }
}

/** Simple dummy adapter used by the test – its read/write methods are never invoked. */
private static final class DummyAdapter<T> extends TypeAdapter<T> {
    @Override
    public void write(JsonWriter out, T value) throws IOException {
        throw new AssertionError("not needed for this test");
    }

    @Override
    public T read(JsonReader in) throws IOException {
        throw new AssertionError("not needed for this test");
    }
}

/**
 * Executes the original test logic and returns the values needed for the individual assertions.
 */
private static ConcurrencyTestResult runConcurrencySetup() {
    final AtomicInteger adapterInstancesCreated = new AtomicInteger(0);
    final AtomicReference<TypeAdapter<?>> threadAdapterRef = new AtomicReference<>();
    final Class<?> requestedType = Number.class;

    Gson gson = new GsonBuilder()
        .registerTypeAdapterFactory(new TypeAdapterFactory() {
            private volatile boolean isFirstCall = true;

            @Override
            public <T> TypeAdapter<T> create(final Gson gson, TypeToken<T> type) {
                if (isFirstCall) {
                    isFirstCall = false;

                    // Create a separate thread which requests an adapter for the same type.
                    Thread thread = new Thread(() -> threadAdapterRef.set(gson.getAdapter(requestedType)));
                    thread.start();
                    try {
                        thread.join();
                    } catch (InterruptedException e) {
                        throw new RuntimeException(e);
                    }
                }

                // Count each created adapter instance.
                adapterInstancesCreated.incrementAndGet();
                return new DummyAdapter<>();
            }
        })
        .create();

    TypeAdapter<?> mainAdapter = gson.getAdapter(requestedType);
    return new ConcurrencyTestResult(
        mainAdapter,
        threadAdapterRef.get(),
        adapterInstancesCreated.get()
    );
}

/** Verifies that exactly two adapter instances are created during the concurrent request. */
@Test
public void testGetAdapter_Concurrency_adapterInstancesCreated() {
    ConcurrencyTestResult result = runConcurrencySetup();
    assertThat(result.adapterInstancesCreated).isEqualTo(2);
}

/** Verifies that the adapter returned to the main thread is a DummyAdapter. */
@Test
public void testGetAdapter_Concurrency_mainAdapterInstance() {
    ConcurrencyTestResult result = runConcurrencySetup();
    assertThat(result.mainAdapter).isInstanceOf(DummyAdapter.class);
}

/** Verifies that the adapter returned to the spawned thread is also a DummyAdapter. */
@Test
public void testGetAdapter_Concurrency_threadAdapterInstance() {
    ConcurrencyTestResult result = runConcurrencySetup();
    assertThat(result.threadAdapter).isInstanceOf(DummyAdapter.class);
}

