/** Helper that unwraps reflection‑related checked exceptions as unchecked AssertionErrors. */
private static Field getField(Class<?> clazz, String fieldName) {
  try {
    return clazz.getField(fieldName);
  } catch (NoSuchFieldException | SecurityException e) {
    throw new AssertionError(
        String.format("Unable to access field \"%s\" on class %s", fieldName, clazz.getName()), e);
  }
}

