/** Helper that creates the JSON output using the same configuration as the original test. */
private static String writeCustomJson() throws IOException {
  StringWriter writer = new StringWriter();
  JsonWriter jsonWriter =
      new GsonBuilder()
          .disableHtmlEscaping()
          .generateNonExecutableJson()
          .setPrettyPrinting()
          .serializeNulls()
          .setLenient()
          .create()
          .newJsonWriter(writer);
  jsonWriter.beginObject();
  jsonWriter.name("test");
  jsonWriter.nullValue();
  jsonWriter.name("<test2");
  jsonWriter.value(true);
  jsonWriter.endObject();

  // Additional top‑level value
  jsonWriter.value(1);
  jsonWriter.close();
  return writer.toString();
}

/** Verifies that the writer produces the expected non‑executable JSON prefix and object content. */
@Test
public void testNewJsonWriter_Custom_writesObject() throws IOException {
  String output = writeCustomJson();
  String prefix = ")]}'\n";

  // Check the non‑executable JSON prefix.
  assertThat(output).startsWith(prefix);

  // Read and verify the JSON object.
  JsonReader reader = new JsonReader(new StringReader(output.substring(prefix.length())));
  assertThat(reader.peek()).isEqualTo(JsonToken.BEGIN_OBJECT);
  reader.beginObject();

  assertThat(reader.nextName()).isEqualTo("test");
  assertThat(reader.peek()).isEqualTo(JsonToken.NULL);
  reader.nextNull();

  assertThat(reader.nextName()).isEqualTo("<test2");
  assertThat(reader.nextBoolean()).isTrue();

  reader.endObject();
  reader.close();
}

/** Verifies that after the object the writer correctly emits the additional top‑level value. */
@Test
public void testNewJsonWriter_Custom_writesAdditionalTopLevelValue() throws IOException {
  String output = writeCustomJson();
  String prefix = ")]}'\n";

  // Skip the prefix and the object; then verify the trailing number token.
  JsonReader reader = new JsonReader(new StringReader(output.substring(prefix.length())));
  reader.beginObject();
  while (reader.hasNext()) {
    reader.nextName();
    reader.skipValue();
  }
  reader.endObject();

  assertThat(reader.peek()).isEqualTo(JsonToken.NUMBER);
  assertThat(reader.nextInt()).isEqualTo(1);
  assertThat(reader.peek()).isEqualTo(JsonToken.END_DOCUMENT);
  reader.close();
}

