/** Helper that writes the given doubles as a JSON array and returns the JSON text. */
private static String writeDoubles(double... values) {
  try {
    StringWriter sw = new StringWriter();
    JsonWriter jw = new JsonWriter(sw);
    jw.beginArray();
    for (double v : values) {
      jw.value(v);
    }
    jw.endArray();
    jw.close();                     // close may throw IOException – fail the test if it does
    return sw.toString();
  } catch (IOException e) {
    fail("Unexpected IOException while writing JSON: " + e.getMessage());
    return null; // unreachable
  }
}

/** Helper that parses a JSON array string and returns the first double value. */
private static double readFirstDouble(String json) {
  try {
    JsonReader jr = new JsonReader(new java.io.StringReader(json));
    jr.beginArray();
    double d = jr.nextDouble();
    jr.endArray();
    jr.close();
    return d;
  } catch (IOException e) {
    fail("Unexpected IOException while reading JSON: " + e.getMessage());
    return Double.NaN; // unreachable
  }
}

