private static void assertFloatSerializesCorrectly(float value, String expectedJson)
    throws IOException {
  // Write the single value to JSON.
  StringWriter stringWriter = new StringWriter();
  JsonWriter jsonWriter = new JsonWriter(stringWriter);
  jsonWriter.beginArray();
  jsonWriter.value(value);
  jsonWriter.endArray();
  jsonWriter.close();

  // Verify the exact JSON representation (original behaviour).
  assertThat(stringWriter.toString()).isEqualTo("[" + expectedJson + "]");

  // Verify the numeric value by reading it back (removes sensitive equality).
  JsonReader jsonReader = new JsonReader(new StringReader(stringWriter.toString()));
  jsonReader.beginArray();
  double read = jsonReader.nextDouble(); // JsonReader returns double for numbers
  jsonReader.endArray();
  jsonReader.close();

  // Use Float.compare for exact bit‑wise equality of the original float.
  assertThat(Float.compare((float) read, value)).isEqualTo(0);
}

