/** Consumes the two {@code null} literals and finishes the array. */
private void consumeNullsAndEndArray(JsonReader reader) throws IOException {
  // The JSON contains two null literals with mixed case; we simply advance past them.
  reader.nextNull();
  reader.nextNull();
  reader.endArray();
}

