  assertThat(reader.nextBoolean()).isTrue();   // "TruE"
  assertThat(reader.nextBoolean()).isFalse();  // "False"
  assertThat(reader.nextBoolean()).isFalse();  // "FALSE"

  // Consume the remaining literals so the reader can be closed cleanly.
  consumeNullsAndEndArray(reader);
}

