/** Builds the JSON string that spans across the internal buffer boundary. */
private static String buildJsonAcrossBuffers() {
  // The JSON starts with a comment‑like prefix that Gson (lenient mode) skips,
  // followed by a numeric value that should be recognised as a NUMBER token.
  return "#" + repeat(' ', JsonReader.BUFFER_SIZE - 3) + "\n)]}'\n3";
}

