  assertClosedWriterThrowsOnValue(writer);
}

/** Creates a {@link JsonWriter} that is already closed. */
private static JsonWriter createClosedWriter() throws IOException {
  JsonWriter writer = new JsonWriter(new StringWriter());
  writer.beginArray();
  writer.endArray();
  writer.close();
  return writer;
}

/** Asserts that calling {@code value} on a closed writer throws the expected exception. */
private static void assertClosedWriterThrowsOnValue(JsonWriter writer) {
  IllegalStateException exception =
      assertThrows(IllegalStateException.class, () -> writer.value("a"));
  assertThat(exception).hasMessageThat().isEqualTo("JsonWriter is closed.");
}

