/**
 * Helper that creates an {@link Element} with the supplied {@code class} attribute
 * and asserts that {@link Element#hasClass(String)} returns the expected result.
 */
private static void assertHasClass(String classAttr, String query, boolean expected) {
    Attributes attribs = new Attributes();
    Element el = new Element(Tag.valueOf("a"), "", attribs);
    attribs.put("class", classAttr);
    boolean actual = el.hasClass(query);
    assertEquals(
        String.format(
            "Class attribute \"%s\" should %scontain class \"%s\"",
            classAttr,
            expected ? "" : "not ",
            query),
        expected,
        actual);
}

