 * @param charset      character set to use, or {@code null} to let Jsoup auto‑detect
 * @param baseUri      the base URI to associate with the parsed document
 * @return the parsed {@link Document}
 */
private Document loadDocument(String resourcePath, String charset, String baseUri) {
    try (InputStream in = getClass().getResourceAsStream(resourcePath)) {
        assertNotNull("Test resource not found: " + resourcePath, in);
        return Jsoup.parse(in, charset, baseUri);
    } catch (IOException e) {
        // Convert to an unchecked exception so the test fails without declaring throws
        throw new UncheckedIOException(e);
    }
}

