private static final int EXPECTED_FORM_DATA_SIZE = 6;

private static final String[][] EXPECTED_FORM_DATA = {
        {"one", "two"},
        {"three", "four"},
        {"three", "five"},
        {"six", "seven"},
        {"seven", "on"},
        {"eight", "on"}
};

@Test
public void createsFormData_checksSizeAndContent() {
    String html = "<form><input name='one' value='two'><select name='three'><option value='not'>"
            + "<option value='four' selected><option value='five' selected><textarea name=six>seven</textarea>"
            + "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>"
            + "<input name='eight' type='checkbox' checked><input name='nine' type='checkbox' value='unset'>"
            + "<input name='ten' value='text' disabled>"
            + "<input name='eleven' value='text' type='button'>"
            + "</form>";
    Document doc = Jsoup.parse(html);
    FormElement form = (FormElement) doc.select("form").first();
    List<Connection.KeyVal> data = form.formData();

    assertEquals("Form data should contain exactly " + EXPECTED_FORM_DATA_SIZE + " entries",
            EXPECTED_FORM_DATA_SIZE, data.size());

    for (int i = 0; i < EXPECTED_FORM_DATA.length; i++) {
        Connection.KeyVal kv = data.get(i);
        String expectedKey = EXPECTED_FORM_DATA[i][0];
        String expectedValue = EXPECTED_FORM_DATA[i][1];
        assertEquals("Unexpected key at index " + i, expectedKey, kv.key());
        assertEquals("Unexpected value at index " + i, expectedValue, kv.value());
    }

    // Verify that excluded elements are indeed omitted
    assertFalse("Unchecked checkbox 'nine' should not be present", containsKey(data, "nine"));
    assertFalse("Disabled input 'ten' should not be present", containsKey(data, "ten"));
    assertFalse("Button input 'eleven' should not be present", containsKey(data, "eleven"));
}

/** Helper to check if a list of KeyVals contains a given key. */
private boolean containsKey(List<Connection.KeyVal> data, String key) {
    return data.stream().anyMatch(kv -> kv.key().equals(key));
}

