private void manipulateTextNodes(Element p) {
    List<TextNode> textNodes = p.textNodes();

    // replace the text inside the <span> element
    textNodes.get(INDEX_SPAN_TEXT).text(" three-more ");

    // split the third text node (" Three ") after 3 characters and replace the new node's text
    textNodes.get(INDEX_THREE_TEXT).splitText(SPLIT_AT).text("-ur");
}

