@Test
public void testHasTextWhenIterating_notBlank() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    List<TextNode> textNodes = collectTextNodes(doc);

    for (TextNode tn : textNodes) {
        assertFalse("TextNode should not be blank", StringUtil.isBlank(tn.text()));
    }
}

@Test
public void testHasTextWhenIterating_firstContent() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    List<TextNode> textNodes = collectTextNodes(doc);

    assertFalse("Document must contain at least one TextNode", textNodes.isEmpty());

    TextNode first = textNodes.get(0);
    assertEquals("One ", first.text());
    assertEquals("One ", first.getWholeText());
}

@Test
public void testHasTextWhenIterating_hasAtLeastOne() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    List<TextNode> textNodes = collectTextNodes(doc);

    assertTrue("At least one TextNode should be found", !textNodes.isEmpty());
}

/** Helper that walks the document tree and returns all TextNode instances in document order. */
private List<TextNode> collectTextNodes(Document doc) {
    List<TextNode> result = new ArrayList<>();
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                result.add((TextNode) node);
            }
        }
    }
    return result;
}

